import * as THREE from 'three';
import { canvas, colorTex, dataTex, loadImage, paint, type Ctx } from '../lib/canvas';
import { fbm2, fbmTile, hash2, noise2, rng, range } from '../lib/rand';

/**
 * Every surface of the pizzeria, drawn in code: the floured oak board, Carrara marble, majolica tiles with lemons,
 * cementine floor tiles, plaster, the oven's soot-black brick and its gold mosaic, the chalkboard, the street.
 * Photo versions (generated by the site owner, processed into public/media/textures) replace a drawn texture
 * when present.
 */

export async function photoOr(base: string, name: string, draw: () => HTMLCanvasElement, repeat?: [number, number]): Promise<THREE.Texture> {
  const img = await loadImage(`${base}media/textures/${name}.webp`);
  if (!img) return colorTex(draw(), repeat);
  const t = new THREE.Texture(img);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  if (repeat) {
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(repeat[0], repeat[1]);
  }
  t.needsUpdate = true;
  return t;
}

/** The spianatoia: a big oak work board, planks along x, dusted with flour (top-down). */
export function oakBoard(w = 1536, h = 1024): HTMLCanvasElement {
  const { c, g } = canvas(w, h);
  const planks = 5;
  paint(g, w, h, (x, y) => {
    const p = Math.floor((y / h) * planks);
    const py = (y / h) * planks - p;
    const n = fbm2(x / 260 + p * 13, y / 30, 3, p);
    const grain = Math.sin((x / 7 + n * 26 + p * 3) * 0.9 + fbm2(x / 50, y / 14, 2, 4 + p) * 6);
    const ring = Math.pow(Math.abs(grain), 6);
    const tone = (hash2(p, 3, 1) - 0.5) * 20;
    const seam = py < 0.012 || py > 0.988 ? -55 : 0;
    const v = (n - 0.5) * 30 - ring * 24 + tone + seam;
    return [196 + v, 156 + v * 0.9, 112 + v * 0.75];
  });
  // Flour: broad dusting, denser towards the middle, hand marks and loose drifts.
  const r = rng(42);
  for (let i = 0; i < 3800; i++) {
    const a = r() * Math.PI * 2;
    const d = Math.pow(r(), 0.7) * Math.min(w, h) * 0.55;
    const x = w / 2 + Math.cos(a) * d * 1.3;
    const y = h / 2 + Math.sin(a) * d * 0.9;
    g.fillStyle = `rgba(250,248,242,${0.05 + r() * 0.12})`;
    g.beginPath();
    g.arc(x, y, 1 + r() * 9, 0, Math.PI * 2);
    g.fill();
  }
  g.globalAlpha = 0.18;
  for (let i = 0; i < 9; i++) {
    const x = range(r, w * 0.15, w * 0.85);
    const y = range(r, h * 0.15, h * 0.85);
    const grad = g.createRadialGradient(x, y, 0, x, y, range(r, 60, 180));
    grad.addColorStop(0, 'rgba(255,253,248,1)');
    grad.addColorStop(1, 'rgba(255,253,248,0)');
    g.fillStyle = grad;
    g.fillRect(0, 0, w, h);
  }
  g.globalAlpha = 1;
  for (let i = 0; i < 7; i++) {
    g.strokeStyle = 'rgba(255,253,248,0.2)';
    g.lineWidth = range(r, 10, 26);
    g.lineCap = 'round';
    g.beginPath();
    const x = range(r, w * 0.2, w * 0.8);
    const y = range(r, h * 0.2, h * 0.8);
    g.moveTo(x, y);
    g.quadraticCurveTo(x + range(r, -160, 160), y + range(r, -60, 60), x + range(r, -260, 260), y + range(r, -90, 90));
    g.stroke();
  }
  return c;
}

/** Old Carrara marble with soft grey veins. */
export function marble(w = 1024, h = 512): HTMLCanvasElement {
  const { c, g } = canvas(w, h);
  paint(g, w, h, (x, y) => {
    const n = fbm2(x / 220, y / 220, 5, 7);
    const t = Math.abs(Math.sin((x / w) * 9 + (y / h) * 3 + n * 9));
    const vein = Math.pow(1 - t, 22) * 0.9 + Math.pow(1 - t, 5) * 0.12;
    const soft = (fbm2(x / 90, y / 90, 3, 2) - 0.5) * 12;
    const warm = fbm2(x / 400, y / 400, 2, 9) > 0.62 ? 6 : 0;
    return [236 - vein * 92 + soft + warm, 234 - vein * 90 + soft, 229 - vein * 82 + soft - warm];
  });
  return c;
}

/** Warm lime plaster, tileable. */
export function plaster(s = 512): HTMLCanvasElement {
  const { c, g } = canvas(s);
  paint(g, s, s, (x, y) => {
    const n = fbmTile(x / 64, y / 64, s / 64, 5, 3);
    const m = fbmTile(x / 16, y / 16, s / 16, 2, 8);
    const v = (n - 0.5) * 30 + (m - 0.5) * 8;
    return [232 + v, 219 + v, 196 + v * 0.9];
  });
  return c;
}

/**
 * Majolica: hand-painted glazed tiles, white ground with cobalt, yellow and green. One canvas holds a 4 × 4 block
 * of two alternating designs (a lemon branch and a star rosette) so the wall doesn't look like one stamp repeated.
 */
export function majolica(tile = 128, n = 4): HTMLCanvasElement {
  const s = tile * n;
  const { c, g } = canvas(s);
  const r = rng(17);
  for (let j = 0; j < n; j++)
    for (let i = 0; i < n; i++) {
      const x = i * tile;
      const y = j * tile;
      const glaze = 236 + Math.floor(r() * 10);
      g.fillStyle = `rgb(${glaze},${glaze - 4},${glaze - 16})`;
      g.fillRect(x, y, tile, tile);
      g.save();
      g.translate(x + tile / 2, y + tile / 2);
      if ((i + j) % 2 === 0) drawLemonTile(g, tile, r);
      else drawRosetteTile(g, tile, r);
      g.restore();
      // Grout and a soft bevel.
      g.strokeStyle = 'rgba(150,140,125,0.9)';
      g.lineWidth = 2.5;
      g.strokeRect(x + 1, y + 1, tile - 2, tile - 2);
      g.strokeStyle = 'rgba(255,255,255,0.4)';
      g.lineWidth = 1;
      g.strokeRect(x + 4, y + 4, tile - 8, tile - 8);
    }
  return c;
}

const COBALT = '#1f4fa3';
const YELLOW = '#e8b52c';
const GREEN = '#3f8a4a';

function drawLemonTile(g: Ctx, t: number, r: () => number): void {
  // Corner quarter-circles in cobalt make a pattern across tiles.
  g.fillStyle = COBALT;
  for (const [cx, cy] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) {
    g.beginPath();
    g.arc((cx * t) / 2, (cy * t) / 2, t * 0.2, 0, Math.PI * 2);
    g.fill();
  }
  g.rotate((Math.floor(r() * 4) * Math.PI) / 2);
  // Branch
  g.strokeStyle = '#6b4a2a';
  g.lineWidth = 2.5;
  g.beginPath();
  g.moveTo(-t * 0.3, t * 0.28);
  g.quadraticCurveTo(-t * 0.05, 0, t * 0.22, -t * 0.25);
  g.stroke();
  // Leaves
  for (const [lx, ly, a] of [[-t * 0.16, t * 0.12, -0.6], [t * 0.05, -t * 0.08, 0.9], [t * 0.16, -t * 0.22, -0.3]]) {
    g.save();
    g.translate(lx, ly);
    g.rotate(a);
    g.fillStyle = GREEN;
    g.beginPath();
    g.ellipse(0, 0, t * 0.11, t * 0.045, 0, 0, Math.PI * 2);
    g.fill();
    g.restore();
  }
  // Two lemons
  for (const [lx, ly, s] of [[t * 0.02, t * 0.14, 1], [-t * 0.12, -t * 0.14, 0.8]]) {
    g.save();
    g.translate(lx, ly);
    g.rotate(0.5);
    g.fillStyle = YELLOW;
    g.beginPath();
    g.ellipse(0, 0, t * 0.13 * s, t * 0.095 * s, 0, 0, Math.PI * 2);
    g.fill();
    g.fillStyle = 'rgba(255,240,180,0.7)';
    g.beginPath();
    g.ellipse(-t * 0.035 * s, -t * 0.03 * s, t * 0.04 * s, t * 0.022 * s, 0, 0, Math.PI * 2);
    g.fill();
    g.fillStyle = YELLOW;
    g.beginPath();
    g.ellipse(t * 0.135 * s, 0, t * 0.02, t * 0.014, 0, 0, Math.PI * 2);
    g.fill();
    g.restore();
  }
}

function drawRosetteTile(g: Ctx, t: number, r: () => number): void {
  g.fillStyle = COBALT;
  g.beginPath();
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2;
    const rad = i % 2 === 0 ? t * 0.42 : t * 0.22;
    g.lineTo(Math.cos(a) * rad, Math.sin(a) * rad);
  }
  g.closePath();
  g.fill();
  g.fillStyle = '#f4efe2';
  g.beginPath();
  g.arc(0, 0, t * 0.2, 0, Math.PI * 2);
  g.fill();
  g.fillStyle = YELLOW;
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2 + r() * 0.05;
    g.beginPath();
    g.ellipse(Math.cos(a) * t * 0.11, Math.sin(a) * t * 0.11, t * 0.06, t * 0.025, a, 0, Math.PI * 2);
    g.fill();
  }
  g.fillStyle = GREEN;
  g.beginPath();
  g.arc(0, 0, t * 0.045, 0, Math.PI * 2);
  g.fill();
  g.fillStyle = 'rgba(31,79,163,0.85)';
  for (const [cx, cy] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
    g.beginPath();
    g.arc((cx * t) / 2, (cy * t) / 2, t * 0.07, 0, Math.PI * 2);
    g.fill();
  }
}

/** Cementine: encaustic cement floor tiles in a four-tile rosette, terracotta, charcoal and cream. */
export function cementine(tile = 128, n = 4): HTMLCanvasElement {
  const s = tile * n;
  const { c, g } = canvas(s);
  for (let j = 0; j < n; j++)
    for (let i = 0; i < n; i++) {
      g.save();
      g.translate(i * tile, j * tile);
      // Each tile is a quarter of a larger rosette; flip it so four tiles meet into one flower.
      g.translate(i % 2 ? tile : 0, j % 2 ? tile : 0);
      g.scale(i % 2 ? -1 : 1, j % 2 ? -1 : 1);
      g.fillStyle = '#e9dfca';
      g.fillRect(0, 0, tile, tile);
      g.fillStyle = '#a4523a';
      g.beginPath();
      g.arc(tile, tile, tile * 0.62, Math.PI, Math.PI * 1.5);
      g.lineTo(tile, tile);
      g.fill();
      g.fillStyle = '#e9dfca';
      g.beginPath();
      g.arc(tile, tile, tile * 0.44, Math.PI, Math.PI * 1.5);
      g.lineTo(tile, tile);
      g.fill();
      g.fillStyle = '#2d2a28';
      for (let k = 0; k < 3; k++) {
        const a = Math.PI + (k + 0.5) * (Math.PI / 6);
        g.beginPath();
        g.ellipse(tile + Math.cos(a) * tile * 0.3, tile + Math.sin(a) * tile * 0.3, tile * 0.1, tile * 0.04, a, 0, Math.PI * 2);
        g.fill();
      }
      g.fillStyle = '#2d2a28';
      g.beginPath();
      g.moveTo(0, 0);
      g.lineTo(tile * 0.24, 0);
      g.lineTo(0, tile * 0.24);
      g.closePath();
      g.fill();
      g.fillStyle = '#a4523a';
      g.beginPath();
      g.arc(0, 0, tile * 0.1, 0, Math.PI / 2);
      g.lineTo(0, 0);
      g.fill();
      g.restore();
    }
  // Wear: grout, scuffs, a little dirt in the joints.
  paintOver(g, s, s, (x, y, p) => {
    const n = fbmTile(x / 32, y / 32, s / 32, 3, 5);
    const k = 0.9 + n * 0.16;
    const joint = x % tile < 2 || y % tile < 2 ? 0.6 : 1;
    return [p[0] * k * joint, p[1] * k * joint, p[2] * k * joint];
  });
  return c;
}

function paintOver(g: Ctx, w: number, h: number, fn: (x: number, y: number, p: Uint8ClampedArray) => number[]): void {
  const img = g.getImageData(0, 0, w, h);
  const d = img.data;
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      const i = (y * w + x) * 4;
      const o = fn(x, y, d.subarray(i, i + 3));
      d[i] = o[0];
      d[i + 1] = o[1];
      d[i + 2] = o[2];
    }
  g.putImageData(img, 0, 0);
}

/** Inside the oven: refractory brick, black with soot, tileable. */
export function sootBrick(s = 512): HTMLCanvasElement {
  const { c, g } = canvas(s);
  const bw = s / 4;
  const bh = s / 8;
  paint(g, s, s, (x, y) => {
    const row = Math.floor(y / bh);
    const off = row % 2 ? bw / 2 : 0;
    const bx = (x + off) % bw;
    const by = y % bh;
    const mortar = bx < 4 || by < 4;
    const id = Math.floor((x + off) / bw) + row * 7;
    const n = fbmTile(x / 32, y / 32, s / 32, 4, 2);
    const tone = hash2(id, row, 3) * 24;
    if (mortar) return [34 + n * 12, 30 + n * 10, 28 + n * 9];
    const v = 46 + tone + n * 26;
    return [v + 8, v * 0.78, v * 0.62];
  });
  return c;
}

/** Old terracotta bricks with lime mortar, tileable (the oven's base). */
export function terracottaBrick(s = 512): HTMLCanvasElement {
  const { c, g } = canvas(s);
  const bw = s / 4;
  const bh = s / 10;
  paint(g, s, s, (x, y) => {
    const row = Math.floor(y / bh);
    const off = row % 2 ? bw / 2 : 0;
    const bx = (x + off) % bw;
    const by = y % bh;
    const mortar = bx < 5 || by < 5;
    const id = Math.floor((x + off) / bw) + row * 7;
    const n = fbmTile(x / 32, y / 32, s / 32, 4, 6);
    if (mortar) return [190 + n * 20, 176 + n * 18, 150 + n * 14];
    const tone = hash2(id, row, 11) * 34 - 17;
    const v = n * 30;
    return [160 + tone + v, 78 + tone * 0.6 + v * 0.6, 52 + tone * 0.4 + v * 0.4];
  });
  return c;
}

/** The oven's cooking floor: biscotto stone, pale, with ash and flour scorch. */
export function ovenFloor(s = 1024): HTMLCanvasElement {
  const { c, g } = canvas(s);
  const tile = s / 4;
  paint(g, s, s, (x, y) => {
    const n = fbm2(x / 90, y / 90, 4, 12);
    const fine = noise2(x / 3, y / 3, 5);
    const ash = fbm2(x / 46, y / 46, 3, 19);
    const scorch = fbm2(x / 160, y / 160, 3, 23);
    const joint = x % tile < 1.5 || y % tile < 1.5 ? -14 : 0;
    let v = 128 + (n - 0.5) * 30 + (fine - 0.5) * 16 + joint;
    v -= Math.max(0, scorch - 0.5) * 150;
    const grey = ash > 0.6 ? (ash - 0.6) * 120 : 0;
    return [v + 14 - grey * 0.2, v * 0.9 + grey * 0.1, v * 0.78 + grey * 0.25];
  });
  return c;
}

/**
 * The mosaic that covers a Neapolitan oven's dome: small tesserae, black ground, a gold band and the name in gold,
 * as the city's pizzerias do. The texture wraps the dome horizontally (u = angle, v = height).
 */
export function mosaic(name: string, w = 2048, h = 512): { color: HTMLCanvasElement; bump: HTMLCanvasElement } {
  const cell = 8;
  const cols = Math.floor(w / cell);
  const rows = Math.floor(h / cell);
  // Rasterise the lettering into the tesserae grid.
  const text = canvas(cols, rows);
  text.g.fillStyle = '#000';
  text.g.fillRect(0, 0, cols, rows);
  text.g.fillStyle = '#fff';
  text.g.font = `800 ${Math.round(rows * 0.26)}px "Fraunces Variable", Georgia, serif`;
  text.g.textAlign = 'center';
  text.g.textBaseline = 'middle';
  // The name sits on the front of the dome: on a three.js sphere u = 0.25 faces +z, the room (see oven.ts).
  text.g.fillText(name, cols * 0.25, rows * 0.56);
  text.g.fillText('✦ 1958 ✦', cols * 0.75, rows * 0.56);
  const tmask = text.g.getImageData(0, 0, cols, rows).data;
  const { c, g } = canvas(w, h);
  const bump = canvas(w, h);
  g.fillStyle = '#8c7451';
  g.fillRect(0, 0, w, h);
  bump.g.fillStyle = '#000';
  bump.g.fillRect(0, 0, w, h);
  const r = rng(3);
  for (let j = 0; j < rows; j++)
    for (let i = 0; i < cols; i++) {
      const letter = tmask[(j * cols + i) * 4] > 110;
      // Rows count from the top of the canvas = the top of the dome (v = 1 there after the remap in oven.ts).
      const fromBottom = rows - 1 - j;
      const band = fromBottom === 2 || fromBottom === 3 || j === Math.round(rows * 0.36) || j === Math.round(rows * 0.76);
      const cobalt = fromBottom === 5 || j === Math.round(rows * 0.38) || j === Math.round(rows * 0.74);
      const crown = j < rows * 0.08;
      let col: [number, number, number];
      if (letter) {
        const k = 0.85 + r() * 0.25;
        col = [120 * k, 24 * k, 18 * k];
      } else if (band || crown) {
        const k = 0.8 + r() * 0.3;
        col = [40 * k, 34 * k, 30 * k];
      } else if (cobalt) col = [30 + r() * 20, 70 + r() * 25, 150 + r() * 40];
      else {
        // Gold leaf glass tesserae, never quite the same twice.
        const k = 0.78 + r() * 0.34;
        col = [226 * k, 178 * k, 74 * k];
      }
      const jx = (r() - 0.5) * 1.6;
      const jy = (r() - 0.5) * 1.6;
      g.fillStyle = `rgb(${col[0] | 0},${col[1] | 0},${col[2] | 0})`;
      g.fillRect(i * cell + 0.5 + jx, j * cell + 0.5 + jy, cell - 1, cell - 1);
      bump.g.fillStyle = `rgb(${200 + Math.floor(r() * 55)},0,0)`;
      bump.g.fillRect(i * cell + 1.5 + jx, j * cell + 1.5 + jy, cell - 3, cell - 3);
    }
  return { color: c, bump: bump.c };
}

/** The chalkboard menu. Lines are [text, size, x, y, align]. */
export function chalkboard(w: number, h: number, draw: (g: Ctx) => void): HTMLCanvasElement {
  const { c, g } = canvas(w, h);
  paint(g, w, h, (x, y) => {
    const n = fbm2(x / 120, y / 120, 4, 2);
    const smear = fbm2(x / 40, y / 300, 2, 8) > 0.6 ? 10 : 0;
    const v = 34 + n * 14 + smear;
    return [v, v + 6, v + 3];
  });
  draw(g);
  return c;
}

/** Rough grey-blue cobbles for the street, tileable, with wet sheen in the roughness map. */
export function cobbles(s = 512): { color: HTMLCanvasElement; rough: HTMLCanvasElement } {
  const { c, g } = canvas(s);
  const rr = canvas(s);
  const cells = 9;
  const pts: [number, number][] = [];
  for (let j = 0; j < cells; j++) for (let i = 0; i < cells; i++) pts.push([(i + 0.2 + hash2(i, j, 1) * 0.6) / cells, (j + 0.2 + hash2(i, j, 2) * 0.6) / cells]);
  const img = g.createImageData(s, s);
  const rimg = rr.g.createImageData(s, s);
  for (let y = 0; y < s; y++)
    for (let x = 0; x < s; x++) {
      const u = x / s;
      const v = y / s;
      let d1 = 9;
      let d2 = 9;
      let id = 0;
      const ci = Math.floor(u * cells);
      const cj = Math.floor(v * cells);
      for (let dj = -1; dj <= 1; dj++)
        for (let di = -1; di <= 1; di++) {
          const ii = ci + di;
          const jj = cj + dj;
          const wi = ((ii % cells) + cells) % cells;
          const wj = ((jj % cells) + cells) % cells;
          const k = wj * cells + wi;
          const px = pts[k][0] + (ii - wi) / cells;
          const py = pts[k][1] + (jj - wj) / cells;
          const dx = u - px;
          const dy = v - py;
          const d = dx * dx + dy * dy;
          if (d < d1) {
            d2 = d1;
            d1 = d;
            id = k;
          } else if (d < d2) d2 = d;
        }
      const edge = Math.sqrt(d2) - Math.sqrt(d1);
      const gap = edge < 0.006;
      const n = noise2(x / 9, y / 9, 4);
      const tone = 70 + hash2(id, 0, 9) * 40 + n * 14;
      const i = (y * s + x) * 4;
      const val = gap ? 30 : tone;
      img.data[i] = val * 0.92;
      img.data[i + 1] = val * 0.95;
      img.data[i + 2] = val * 1.05;
      img.data[i + 3] = 255;
      const wet = gap ? 90 : 60 + (1 - Math.min(1, edge * 30)) * 60;
      rimg.data[i] = wet;
      rimg.data[i + 1] = wet;
      rimg.data[i + 2] = wet;
      rimg.data[i + 3] = 255;
    }
  g.putImageData(img, 0, 0);
  rr.g.putImageData(rimg, 0, 0);
  return { color: c, rough: rr.c };
}

/** Weathered Neapolitan stucco (ochre / faded pink), tileable. */
export function stucco(s = 512, hue: [number, number, number] = [214, 160, 112]): HTMLCanvasElement {
  const { c, g } = canvas(s);
  paint(g, s, s, (x, y) => {
    const n = fbmTile(x / 64, y / 64, s / 64, 5, 31);
    const stain = fbmTile(x / 128, y / 32, s / 128, 3, 7);
    const flake = fbmTile(x / 32, y / 32, s / 32, 3, 13) > 0.7 ? 0.82 : 1;
    const k = (0.82 + n * 0.3) * flake * (stain > 0.62 ? 0.9 : 1);
    return [hue[0] * k, hue[1] * k, hue[2] * k];
  });
  return c;
}

/** A plain-tinted linear texture helper for roughness maps. */
export function roughFrom(c: HTMLCanvasElement, repeat?: [number, number]): THREE.Texture {
  return dataTex(c, repeat);
}

/**
 * Relief for a grid of glazed tiles (n × n tiles of `tile` px): a recessed grout line, a soft bevel up to the glaze,
 * a slight random tilt per tile and a faint ripple in the glaze. Returns an OpenGL normal map and a roughness map
 * (glaze shiny, grout matte), both tileable, aligned with majolica() / plainTiles() of the same layout.
 */
export function tileRelief(tile = 128, n = 4, grout = 3, bevel = 7): { normal: HTMLCanvasElement; rough: HTMLCanvasElement } {
  const s = tile * n;
  const height = new Float32Array(s * s);
  const tilt: [number, number][] = [];
  for (let i = 0; i < n * n; i++) tilt.push([(hash2(i, 1, 7) - 0.5) * 0.9, (hash2(i, 2, 7) - 0.5) * 0.9]);
  for (let y = 0; y < s; y++)
    for (let x = 0; x < s; x++) {
      const tx = x % tile;
      const ty = y % tile;
      const id = Math.floor(y / tile) * n + Math.floor(x / tile);
      const edge = Math.min(tx, ty, tile - 1 - tx, tile - 1 - ty);
      let h = edge < grout ? 0 : Math.min(1, (edge - grout) / bevel);
      h = h * h * (3 - 2 * h);
      const [ax, ay] = tilt[id];
      const ripple = (fbmTile(x / 24, y / 24, s / 24, 2, 5) - 0.5) * 0.12;
      height[y * s + x] = h + (edge >= grout ? ((tx / tile - 0.5) * ax + (ty / tile - 0.5) * ay) * 0.25 + ripple : 0);
    }
  const normal = canvas(s);
  const rough = canvas(s);
  const ni = normal.g.createImageData(s, s);
  const ri = rough.g.createImageData(s, s);
  const at = (x: number, y: number): number => height[((y + s) % s) * s + ((x + s) % s)];
  const strength = 2.2;
  for (let y = 0; y < s; y++)
    for (let x = 0; x < s; x++) {
      const dx = (at(x + 1, y) - at(x - 1, y)) * strength;
      const dy = (at(x, y + 1) - at(x, y - 1)) * strength;
      const len = Math.hypot(dx, dy, 1);
      const i = (y * s + x) * 4;
      // OpenGL convention: +y up; canvas rows grow downwards, so the y slope flips.
      ni.data[i] = ((-dx / len) * 0.5 + 0.5) * 255;
      ni.data[i + 1] = ((dy / len) * 0.5 + 0.5) * 255;
      ni.data[i + 2] = ((1 / len) * 0.5 + 0.5) * 255;
      ni.data[i + 3] = 255;
      const tx = x % tile;
      const ty = y % tile;
      const edge = Math.min(tx, ty, tile - 1 - tx, tile - 1 - ty);
      const r = edge < grout ? 235 : 40 + fbmTile(x / 40, y / 40, s / 40, 2, 9) * 50;
      ri.data[i] = r;
      ri.data[i + 1] = r;
      ri.data[i + 2] = r;
      ri.data[i + 3] = 255;
    }
  normal.g.putImageData(ni, 0, 0);
  rough.g.putImageData(ri, 0, 0);
  return { normal: normal.c, rough: rough.c };
}

/** Plain glazed tiles, each a slightly different shade (the dark green skirting of the side walls). */
export function plainTiles(rgb: [number, number, number], tile = 128, n = 4, grout = 3): HTMLCanvasElement {
  const s = tile * n;
  const { c, g } = canvas(s);
  paint(g, s, s, (x, y) => {
    const tx = x % tile;
    const ty = y % tile;
    const edge = Math.min(tx, ty, tile - 1 - tx, tile - 1 - ty);
    if (edge < grout) return [176, 168, 152];
    const id = Math.floor(y / tile) * n + Math.floor(x / tile);
    const k = 0.86 + hash2(id, 3, 1) * 0.22 + (fbmTile(x / 32, y / 32, s / 32, 3, 4) - 0.5) * 0.1;
    // Glaze pools darker towards the edges.
    const pool = edge < grout + 10 ? 0.9 : 1;
    return [rgb[0] * k * pool, rgb[1] * k * pool, rgb[2] * k * pool];
  });
  return c;
}
